async function testServer(server,b){await busy(b,async()=>{try{const data=await request('/test-server',{method:'POST',body:{id:server.id}});connection.set(server.id,{...data,ok:true,at:Date.now()});render();showNotice('连接成功。地图：'+(data.map||'未知')+'；阵营：'+(data.factions?.join('、')||'未返回'));}catch(error){connection.set(server.id,{ok:false,at:Date.now()});render();throw error;}});}
